from pathlib import Path
import json,shutil
P=Path(__file__).resolve().parent;N=P.parents[1];T=json.load(open(P/'targets.json'));S=json.load(open(P/'selection.json'));D=P/'source-inputs';D.mkdir(exist_ok=True)
source=N/'expansion-20261114/szeged-miskolc/miskolc-features.geojson';comps=[f for f in json.load(open(source))['features'] if f['properties']['name'] in ['Selyemrét','Vologda','Jókai-lakótelep']];parents=json.load(open(N/'sources/municipal-local-map-next/miskolc-source-raster.geojson'))['features'];comps+=[f for f in parents if f['properties']['sourceUnitNumber']==2]
(D/'existing-miskolc-components.geojson').write_text(json.dumps({'type':'FeatureCollection','features':comps},ensure_ascii=False,indent=2)+'\n');shutil.copyfile(N/'expansion-20261115-round3/tokaj-centre/source-contexts.geojson',D/'tokaj-native-urban.geojson')
