def add(city,name,kind,note,**kwargs):
 m=next(m for m in T['municipalities'] if m['municipality']==city);t=next(t for t in m['targets'] if t['name']==name);s={'municipality':city,'name':name,'contextKey':m['contextKey'],'kind':kind,'approximationNote':note,'batch':4,'supportingUrls':[]}
 if t['pointCandidates']:s['pointSource']=t['pointCandidates'][0]
 s.update(kwargs);S.append(s)
add('Miskolc','Martin kertvárosi felüljáró','area','The official ITS table identifies this as KSH statistical unit 8, separately from Martin kertváros and within the Selyemrét–Keleti planning group. Its approximate search footprint uses the whole literal rail-transport site at the Martin access/overpass, including the railway approaches rather than a tiny bridge. The exact KSH border is not published in the source map and this physical-site association is inferred.',sourceAreaIds=['osm:way:154537333'],supportingUrls=[MURL,'https://miskolciszemelvenyek.blog.hu/2021/07/08/y-hid'])
add('Miskolc','Szondi telep – Csorbatelep','parentRemainder','The official constituent table places only Szondi telep–Csorbatelep, Martin kertvárosi felüljáró and Selyemrét in ITS group 2. This broad combined statistical-area estimate takes the published group extent after removing the existing coarse Selyemrét estimate and literal Martin railway site. It includes northern commercial/industrial and historical Csorba land, not only the current Szondi housing site. Internal partition borders are inferred and low confidence; raster-map registration is coarse.',parentId='manual:miskolc-source-raster:2',excludeComponentIds=['expansion:miskolc:coarse:selyemret'],excludeAreaIds=['osm:way:154537333'],supportingUrls=[MURL])
add('Miskolc','Vologda–Jókai lakótelep','importUnion','The official ITS table identifies KSH unit 14 as Vologda–Jókai lakótelep. Union of the separately archived low-confidence Vologda and Jókai estate outlines; the two neighborhoods are constituent areas, not aliases of one another. Their historical combined statistical boundary remains uncertain.',componentIds=['expansion:miskolc:coarse:vologda','expansion:miskolc:coarse:jokai'],supportingUrls=[MURL])
add('Tokaj','Halászfalu','externalAreaMask','Municipal TAK explicitly bounds Halászfalu by Rév köz–Szepesy L.–Mosolygó I.–Zákó köz–Bodrogpart. A coarse mask follows the corresponding current mapped streets (Szepsi László, Mosolygó József, Zakó köz), including frontage uncertainty, and intersects the literal native urban footprint for the shoreline. This represents the whole riverfront quarter rather than one small block; street-name transcription and frontage positions remain approximate.',maskId='tokaj-halaszfalu-street-mask',supportingUrls=['https://old.tokaj.hu/wp-content/uploads/2017/12/TAK-Tokaj_k-2.pdf','https://tokaj.hu/hirek/koezlemenyek?start=88'])
add('Vaja','Vajai Ipari park','roadHull','Whole approximate industrial-development envelope along the mapped Nyárfa/Hársfa access streets and industrial parcel beside Rohodi út. The city confirms the Rohodi-road industrial development; developed and reserve land are included, while exact legal park membership remains uncertain.',sourceLineIds=['osm:way:195159227','osm:way:195159268'],sourceAreaIds=['osm:way:586561553'],supportingUrls=['https://vaja.hu/a-joomla-hasznalata/bovitmenyek/komponensek/tartalom-komponens/cikk-kategoriak/369-iparterulet-fejlesztese-a-rohodi-ut-menten'])
S[-1]['kind']='sourceHull'
add('Nyírmártonfalva','Nyíradony-Gúthpuszta','cell','Whole compact forestry settlement enclosure at Gúthpuszta, using the actual local road network and municipality edge. The forestry operator lists municipality Nyírmártonfalva with postal address Nyíradony-Gúthpuszta, explaining the apparent city-name mismatch. This is the inhabited forestry locality, not the entire roughly 5000 ha Gúthi forest; the historical puszta extent is uncertain.',cellId='nyirmartonfalva-3d4a5651:Nyíradony-Gúthpuszta:street',supportingUrls=['https://nyirerdo.hu/wp-content/uploads/2024/09/NYIRERDO_Zrt-Erdeszetek-elerhetosege.pdf','https://nyirerdo.hu/kapcsolat/'])
assert len(S)==66
(P/'selection.json').write_text(json.dumps(S,ensure_ascii=False,indent=2)+'\n')
